<?php
declare(strict_types=1);require dirname(__DIR__,2).'/bootstrap.php';use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\JudgeDirectoryService;use App\Services\CountryFlagService;Auth::requireAdmin();$pdo=Database::connection();JudgeDirectoryService::ensure($pdo);$notice='';if($_SERVER['REQUEST_METHOD']==='POST'&&Csrf::verify($_POST['_csrf']??null)){try{$j=JudgeDirectoryService::findOrCreate($pdo,(string)($_POST['full_name']??''),$_POST);$notice='Judge ready: '.$j['full_name'].' · '.$j['judge_code'];}catch(Throwable $e){$notice=$e->getMessage();}}$rows=$pdo->query("SELECT * FROM bdc_judges ORDER BY status='active' DESC,full_name")->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Judge Directory | BDC</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="../">BDC Admin</a><a class="btn btn-light btn-sm" href="../scoring/">Scoring</a></div></nav><main class="container py-4"><h1 class="h2">Judge Directory</h1><p class="text-muted">Reusable judge identity for scoring selection and event projection.</p><?php if($notice):?><div class="alert alert-info"><?=e($notice)?></div><?php endif;?><form method="post" class="card shadow-sm mb-4"><div class="card-body"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><div class="row g-2"><div class="col-md-3"><input name="full_name" class="form-control" placeholder="Judge full name" required></div><div class="col-md-2"><input name="country" class="form-control" placeholder="Country"></div><div class="col-md-3"><input name="photo_url" class="form-control" placeholder="Photo URL optional"></div><div class="col-md-2"><input name="instagram" class="form-control" placeholder="Instagram optional"></div><div class="col-md-2"><button class="btn btn-dark w-100">Create Judge</button></div></div></div></form><div class="card shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Judge</th><th>Country</th><th>Photo</th><th>Instagram</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $j):?><tr><td><strong><?=e($j['full_name'])?></strong><div class="small text-muted"><?=e($j['judge_code'])?></div></td><td><?=e(CountryFlagService::emoji($j['country_code']?:$j['country']))?> <?=e((string)$j['country'])?></td><td><?=!empty($j['photo_url'])?'✓':'—'?></td><td><?=e((string)$j['instagram'])?></td><td><?=e($j['status'])?></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>